import {hearButton} from './play-media.mjs';
// Smaller parallel examples use the same helper record shape as story/café help.
// Original question attempts and helper attempts always stay in different arrays.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const array=(rows,cols)=>({type:'array',rows,cols});
export function broadHelper(q){
 const p=q.params;let h;const base={id:`${q.id}-smaller`,title:'A smaller example with Pip',kind:'number',lesson:'Try this different example together. Your own question will wait.',facts:[]};
 switch(p.type){
 case 'bundle':{const t=p.tens===2?1:2;h={model:{type:'place',hundreds:0,tens:t,ones:3},prompt:`What number is ${t} tens and 3 ones?`,answer:t*10+3,explanation:`${t} bundles of ten are ${t*10}. Add 3 loose ones: ${t*10+3}.`};break;}
 case 'value':{const t=p.tens===2?3:2;h={model:{type:'place',hundreds:0,tens:t,ones:1},prompt:`In ${t*10+1}, what is the value of the digit ${t}?`,answer:t*10,explanation:`The digit is on the tens shelf: ${t} tens have value ${t*10}.`};break;}
 case 'tens':h={model:{type:'place',hundreds:0,tens:2,ones:1},prompt:'Start with 21 seeds. Add one bundle of ten. How many now?',answer:31,explanation:'21 + 10 = 31. One more ten joins the tens; the one stays.'};break;
 case 'add':h={model:{type:'compare',labels:['First collection','Joining collection'],counts:[3,2]},prompt:'Join 3 berries and 2 berries. How many?',answer:5,explanation:'3 and 2 more make 5. Joining is addition.'};break;
 case 'subtract':h={model:{type:'compare',labels:['Starting muffins','Muffins given away'],counts:[5,2]},prompt:'Start with 5 muffins and give away 2. How many remain?',answer:3,explanation:'5 − 2 = 3. Taking away reduces the collection.'};break;
 case 'group':case 'share':case 'area':{const cols=p.rows===2&&p.cols===2?3:2,sharing=p.type==='share';h={model:array(2,cols),prompt:sharing?`Share ${2*cols} counters equally into 2 rows. How many in a row?`:`How many counters are in 2 rows of ${cols}?`,answer:sharing?cols:2*cols,explanation:`Each row has ${cols}. Two rows hold ${2*cols}.`,facts:[[2,cols]]};break;}
 case 'packs':h={model:array(2,2),prompt:'Two bags have 2 crackers each. Add 2 loose crackers. How many?',answer:6,explanation:'2 × 2 = 4 in bags. Then 4 + 2 = 6.',facts:[[2,2]]};break;
 case 'fractionName':{const d=p.parts===2?3:2;h={kind:'choice',model:{type:'fraction',parts:d,shaded:1},prompt:'How much is colored in?',choices:[`One of ${d} equal parts`,'All of it'],answer:0,explanation:`The whole has ${d} equal parts; only one part is chosen.`};break;}
 case 'part':{const d=p.parts===2?3:2;h={model:{type:'fraction',parts:d,shaded:1},prompt:`Share ${d*2} seeds into ${d} equal groups. How many in one group?`,answer:2,explanation:`${d*2} ÷ ${d} = 2. One equal share has 2 seeds.`,facts:[[d,2]]};break;}
 case 'sequence':{const start=p.start===1&&p.step===2?0:1;h={model:{type:'pattern',values:[start,start+2,start+4],step:2},prompt:`Start at ${start} and add 2: ${start}, ${start+2}, ${start+4}, __. What comes next?`,answer:start+6,explanation:`One more jump of 2 from ${start+4} reaches ${start+6}.`};break;}
 case 'shapeName':case 'corners':h={model:{type:'text',segments:['A pentagon has five straight edges.','Each neighboring pair meets at a corner.'],clue:'Trace the boundary once.'},prompt:'A pentagon has 5 straight sides. How many corners?',answer:5,explanation:'Each pair of neighboring sides meets at a corner. Five sides make five corners.'};break;
 case 'symmetry':{const square=p.shape!=='square';h={kind:'choice',model:{type:'text',segments:[square?'Imagine a square piece of paper.':'Imagine a long rectangular piece of paper.','Fold from one corner to the opposite corner.'],clue:'Do all the edges meet after the fold?'},prompt:'Do the two halves match after this diagonal fold?',choices:['Yes','No'],answer:square?0:1,explanation:square?'A square’s diagonal fold matches both halves.':'A rectangle with different side lengths does not match along its diagonal.'};break;}
 case 'turn':h={kind:'choice',model:{type:'text',segments:['Begin facing east.','Make one quarter-turn clockwise.'],clue:'Clockwise goes north, east, south, west.'},prompt:'Which way are you facing?',choices:['North','South'],answer:1,explanation:'From east, one clockwise quarter-turn reaches south.'};break;
 case 'ribbon':h={model:{type:'ruler',start:1,end:4,max:5},prompt:'A little ribbon goes from 1 cm to 4 cm. How long?',answer:3,explanation:'Count the three spaces: 1 to 2, 2 to 3, 3 to 4. 4 − 1 = 3 cm.'};break;
 case 'perimeter':case 'missingSide':h={model:{type:'text',segments:['A small rectangle is 2 m long.','It is 1 m wide.'],clue:'Walk around: length, width, length, width.'},prompt:'How many meters around the outside?',answer:6,explanation:'2 + 1 + 2 + 1 = 6 m. Both lengths and both widths belong to the boundary.'};break;
 case 'missing':h={model:{type:'compare',labels:['Known part','Whole'],counts:[2,5]},prompt:'2 + __ = 5. What is missing?',answer:3,explanation:'2 and 3 make 5. Check by putting 3 in the space.'};break;
 case 'story':h={model:{type:'text',segments:['Start with 5 buttons.','Give away 2.','Find 1 more.'],clue:'Track one change at a time.'},prompt:'How many buttons at the end?',answer:4,explanation:'5 − 2 = 3. Then 3 + 1 = 4.'};break;
 case 'claim':case 'double':h={model:array(2,2),prompt:'Add one whole new row of 2 to these 2 rows of 2. How many counters now?',answer:6,explanation:'The original 4 counters gain 2 more: 6 altogether. Changing a row can change the total.',facts:[[2,2],[3,2]]};break;
 }
 if(p.type==='packs'&&p.rows===2&&p.cols===2&&p.extra===2&&p.sign===1)h={...h,prompt:'Two bags have 2 crackers each. Add 1 loose cracker. How many?',answer:5,explanation:'2 × 2 = 4. Then 4 + 1 = 5.'};
 if(p.type==='missing'&&p.known===2&&p.total===5)h={...h,model:{type:'compare',labels:['Known part','Whole'],counts:[1,3]},prompt:'1 + __ = 3. What is missing?',answer:2,explanation:'1 and 2 make 3.'};
 if(p.type==='ribbon'&&p.start===1&&p.length===3)h={...h,model:{type:'ruler',start:0,end:2,max:3},prompt:'A little ribbon goes from 0 cm to 2 cm. How long?',answer:2,explanation:'Two spaces, each one centimeter, make 2 cm.'};
 return {...base,...h};
}
export function broadHelperLimit(h){const m=h.model;return m.type==='array'?m.rows:m.type==='ruler'?m.end-m.start:m.type==='place'?m.tens:m.type==='fraction'?m.parts:m.type==='pattern'?m.values.length:m.type==='compare'?m.labels.length:m.segments.length;}
export function openBroadHelp(q,active){const h=broadHelper(q);active.helpUsed=true;if(active.helper?.exampleId!==h.id)active.helper={exampleId:h.id,open:true,attempts:[],input:'',choice:null,error:'',steps:0,spotlight:null,revealed:false};active.helper.open=true;return h;}
export function submitBroadHelp(q,active,value){const h=broadHelper(q),x=active.helper;if(!x?.open||!Number.isInteger(value)||value<0||(h.kind==='choice'&&value>=h.choices.length))return false;x.attempts.push(value);x.error='';return value===h.answer;}
export function broadHelpModelAction(q,active,action){const h=broadHelper(q),x=active.helper;if(!x?.open)return;const max=broadHelperLimit(h);if(action==='step')x.steps=Math.min(max,(x.steps||0)+1);if(action==='recount')x.steps=0;if(action.startsWith('spot:')){const i=Number(action.slice(5));if(Number.isInteger(i)&&i>=0&&i<max)x.spotlight=i;}x.modelUsed=true;}
function model(h,x){const m=h.model,limit=broadHelperLimit(h),step=`<div class="summary-links"><button class="secondary" data-broad-help-action="step" ${x.steps>=limit?'disabled':''}>Explore the next part</button><button class="text-button" data-broad-help-action="recount">Start the picture again</button></div>`;
 if(m.type==='array')return `<div class="helper-array" role="img" aria-label="${m.rows} rows of ${m.cols}">${Array.from({length:m.rows},(_,i)=>`<div class="helper-row ${i<x.steps?'counted':''}">${'<span></span>'.repeat(m.cols)}</div>`).join('')}</div><p class="model-readout">${x.steps} rows counted: ${x.steps*m.cols} counters.</p>${step}`;
 if(m.type==='place')return `<div class="place-board" role="img" aria-label="${m.tens} tens and ${m.ones} ones"><div><strong>Tens</strong>${'<i>10</i>'.repeat(m.tens)}</div><div><strong>Ones</strong>${'<i>1</i>'.repeat(m.ones)}</div></div><p>${x.steps} ten bundles explored.</p>${step}`;
 if(m.type==='fraction')return `<div class="fraction-bar" role="img" aria-label="One whole divided into ${m.parts} equal parts, one shaded" style="grid-template-columns:repeat(${m.parts},1fr)">${Array.from({length:m.parts},(_,i)=>`<span class="${i<m.shaded?'shaded':''}"></span>`).join('')}</div><p>${x.steps} equal parts explored.</p>${step}`;
 if(m.type==='pattern')return `<div class="pattern-tiles">${m.values.map((n,i)=>`<span${i<x.steps?' class="counted"':''}>${n}</span>`).join('')}</div><p>Each jump adds ${m.step}.</p>${step}`;
 if(m.type==='ruler')return `<p>Ribbon: ${m.start} cm → ${m.end} cm.</p><div class="pattern-tiles">${Array.from({length:limit},(_,i)=>`<span>${m.start+i} → ${m.start+i+1}${i<x.steps?' ✓':''}</span>`).join('')}</div><p>${x.steps} one-centimeter spaces counted.</p>${step}`;
 const segments=m.type==='compare'?m.labels.map((label,i)=>`${label}: ${m.counts[i]}`):m.segments;return `<div class="helper-text">${segments.map((s,i)=>`<button type="button" class="helper-tile ${x.spotlight===i?'selected':''}" data-broad-help-action="spot:${i}" aria-pressed="${x.spotlight===i}">${esc(s)}</button>`).join('')}</div>${x.spotlight!==null&&m.clue?`<p>${esc(m.clue)}</p>`:''}`;
}
export function renderBroadHelp(q,active){const h=broadHelper(q),x=active.helper;if(!x?.open)return '';const correct=x.attempts.at(-1)===h.answer;return `<section class="helper-sheet" aria-labelledby="broad-help-title"><p class="place-name">A little help, at your pace</p><h2 id="broad-help-title" tabindex="-1">${esc(h.title)}</h2><p>Your question “${esc(q.title)}” is waiting. This is a different example.</p><p>${esc(h.lesson)}</p>${hearButton(h.lesson,'Hear the example idea')}<section class="helper-model" aria-label="Explore the smaller example">${model(h,x)}</section><p class="question">${esc(h.prompt)}</p>${hearButton(h.prompt,'Hear the example question')}<form id="broad-help-answer-form" novalidate>${h.kind==='choice'?`<div class="choices">${h.choices.map((c,i)=>`<button type="button" class="choice ${x.choice===i?'selected':''}" data-broad-help-choice="${i}" aria-pressed="${x.choice===i}">${esc(c)}</button>`).join('')}</div>`:`<label for="broad-help-answer">Your example answer</label><input id="broad-help-answer" inputmode="numeric" autocomplete="off" value="${esc(x.input)}" aria-describedby="broad-help-error">`}<button class="primary" type="submit">Try the example</button><p id="broad-help-error" role="alert">${esc(x.error||'')}</p></form><div aria-live="polite">${x.attempts.length?`<p class="feedback ${correct?'success':''}">${correct?'That fits this example. You can return whenever you like.':'We can look again or work it out together.'}</p>`:''}</div>${x.revealed?`<div class="solution">${esc(h.explanation)}${hearButton(h.explanation,'Hear this explanation')}</div>`:'<button class="text-button" id="broad-help-explain">Work it out together</button>'}<div class="next-row"><button class="primary" id="broad-help-return">Return to my question</button></div><p class="tiny">Your question is still waiting for you.</p><details class="grownup-note"><summary>For grown-ups</summary><p class="tiny">This example is support. It does not count as an answer to the waiting question, and it does not finish it.</p></details></section>`;}

export function cleanBroadHelp(q,active){
 if(active.helper||active.helpUsed)active.helpUsed=true;
 const x=active.helper,h=broadHelper(q);if(!x||typeof x!=='object'||Array.isArray(x)||x.exampleId!==h.id){delete active.helper;return;}
 const limit=broadHelperLimit(h);x.open=x.open===true;
 x.attempts=Array.isArray(x.attempts)?x.attempts.filter(v=>Number.isInteger(v)&&v>=0&&(h.kind!=='choice'||v<h.choices.length)):[];
 x.steps=Number.isInteger(x.steps)?Math.max(0,Math.min(limit,x.steps)):0;
 x.spotlight=Number.isInteger(x.spotlight)&&x.spotlight>=0&&x.spotlight<limit?x.spotlight:null;
 x.choice=Number.isInteger(x.choice)&&x.choice>=0&&x.choice<(h.choices?.length||0)?x.choice:null;
 x.input=typeof x.input==='string'?x.input.slice(0,30):'';x.error=typeof x.error==='string'?x.error.slice(0,200):'';
 x.revealed=x.revealed===true;x.modelUsed=x.modelUsed===true;
}
